  color: var(--fg-muted);
  padding: 8px 0 8px 18px;
  margin-left: -2px;
  border-left: 2px solid transparent;
  line-height: 1.35;
  transition: color .15s, border-color .15s;
}
.article-toc a::before {
  content: counter(toc, decimal-leading-zero);
