  return pageMetadata({
    title: o.title || 'Documents — Third Eye Worldwide',
    description: o.description || d.heroSub || 'Blogs, stories, and long-form writing from the TEWW team and community.',
    path: '/documents',
    image: o.image,
    noindex: o.noindex,
  });
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars
function chunk<T>(arr: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function BlogsTab({ blogs, cats }: { blogs: any[]; cats: string[] }) {
  return (
    <>
      <section className="section">
        <div className="section-inner">
          <FilterableBlogGrid blogs={blogs} cats={cats} />
        </div>
      </section>
      <section className="section section-alt">
        <div className="section-inner">
          <NewsletterForm />
        </div>
      </section>
    </>
  );
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function StoriesTab({ stories, fs }: { stories: any[]; fs: any }) {
  return (
    <section className="section">
      <div className="section-inner">
        <div className="section-heading left" style={{ maxWidth: 720, marginBottom: 32 }}>
          <div className="section-eyebrow">Stories</div>
          <h2 className="section-title">Voices from our community</h2>
          <p className="section-subtitle">
            Real people, real independence. These are the stories that remind us why the work matters.
          </p>
        </div>

        <FeaturedStory fs={fs} />

        <h3 className="stories-list-heading">More stories</h3>
        {stories.length > 0 ? (
          <div className="doc-grid">
            {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
            {stories.map((s: any) => <DocCard key={s.id || s.title} doc={s} defaultKind="story" />)}
          </div>
        ) : (
          <p style={{ color: 'var(--fg-muted)' }}>No stories yet.</p>
        )}

        {stories.length > 6 ? (
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: 48 }}>
            <button type="button" className="btn-secondary">Load more stories</button>
          </div>
        ) : null}
      </div>
    </section>
  );
}

export default function DocumentsPage() {
  return (
    <Suspense fallback={<SkeletonHero />}>
      <DocumentsPageContent />
    </Suspense>
  );
}

async function DocumentsPageContent() {
  // DB hiccup → empty sections, not a 500. See app/page.tsx.
  let content = null;
  try {
    content = await getContent();
  } catch {
    // fall through to empty-content render
  }
  const d = content?.documents || {};
  const blogs = visibleSorted(d.blogs || []);
  const stories = visibleSorted(d.stories || []);
  const fs = d.featuredStory || {};
  const book = (d.book || {}) as BookContent;
  const cats = Array.from(new Set(blogs.map((b) => (b as { cat?: string }).cat).filter(Boolean))) as string[];
  const tabs: { id: string; label: string; content: React.ReactNode }[] = [
    { id: 'blogs', label: 'Research', content: <BlogsTab blogs={blogs} cats={cats} /> },
    { id: 'stories', label: 'Stories', content: <StoriesTab stories={stories} fs={fs} /> },
  ];
  // Only mount the Book tab if the CMS has any chapters configured —
  // keeps it from showing as an empty section on a fresh install.
  if (book?.chapters && book.chapters.length > 0) {
    tabs.push({ id: 'book', label: 'Book', content: <BookTab book={book} /> });
  }

  return (
    <>
      <div className="page-hero">
        <div className="page-hero-inner">
          <div className="section-eyebrow">{d.heroEyebrow || 'Documents'}</div>
          <RichText as="h1" html={d.heroTitle || 'Read deeper.'} />
          {d.heroSub ? <p>{d.heroSub}</p> : null}
        </div>
      </div>

      <Subnav
        page="documents"
        ariaLabel="Documents sections"
        defaultTab="blogs"
        tabs={tabs}
      />
    </>
  );
}

import Link from 'next/link';

/*
 * Documents blog/story tile. Renders as a full-card link.
 *
 * `doc` shape: { title, desc, heroType, tagClass, tagLabel, cat,
 *                author, initials, meta, readTime, extra }.
 * `defaultKind` decides the link target when tagClass isn't set.
 */
interface Doc {
  tagClass?: string;
  heroType?: string;
  tagLabel?: string;
  extra?: string;
  cat?: string;
  title?: string;
  desc?: string;
  author?: string;
  initials?: string;
  meta?: string;
  readTime?: string;
  id?: string;
}
interface DocCardProps {
  doc?: Doc;
  defaultKind?: 'blog' | 'story';
}

export default function DocCard({ doc, defaultKind = 'blog' }: DocCardProps) {
  const {
    tagClass, heroType, tagLabel, extra, cat,
    title, desc, author, initials = 'TE', meta, readTime,
  } = doc || {};

  const kind = tagClass === 'story' ? 'story' : 'blog';
  const href = kind === 'story' ? '/story-detail' : '/blog-detail';
  const displayHero = heroType || (kind === 'story' ? 'type-story' : 'type-blog');
  const displayTagClass = tagClass || defaultKind;
  const displayTagLabel = tagLabel || (defaultKind === 'story' ? 'Story' : 'Blog');

  return (
    <Link
      className={`doc-card ${extra || ''}`.trim()}
      href={href}
      aria-label={`Read: ${title}`}
      data-cat={cat || ''}
    >
      <div className={`doc-hero ${displayHero}`}>
        <div>
          <span className={`cat-tag ${displayTagClass}`}>{displayTagLabel}</span>
          <h3>{title}</h3>
        </div>
      </div>
      <div className="doc-body">
        <p>{desc}</p>
        <div className="doc-meta">
          <div className="doc-author">
            <div className="avatar">{initials}</div>
            <span>{author || ''}</span>
          </div>
          <span className="sep">·</span>
          <span>{meta || readTime || ''}</span>
        </div>
      </div>
    </Link>
  );
}

'use client';

import { useState } from 'react';
import DocCard from '@/components/documents/DocCard';
import { cn } from '@/lib/utils';

/*
 * Filter pills + card grid for the blogs subpage.
 * `cats` is the unique list of blog categories; 'all' is injected.
 *
 * Uses a single .doc-grid with auto-fit tracks so cards reflow
 * cleanly as the list is filtered (no JS chunking into fixed rows).
 */
export interface Blog {
  id?: string;
  title?: string;
  cat?: string;
  excerpt?: string;
  [k: string]: unknown;
}
export interface FilterableBlogGridProps {
  blogs: Blog[];
  cats: string[];
}

export default function FilterableBlogGrid({ blogs, cats }: FilterableBlogGridProps) {
  const [filter, setFilter] = useState('all');
  const visible = filter === 'all' ? blogs : blogs.filter((b: Blog) => b.cat === filter);

  return (
    <>
      {cats.length > 0 ? (
        <div className="filter-bar" data-filter-group="blogs">
          <div className="filter-label">Topic</div>
          <button
            type="button"
            className={cn('filter-pill', { active: filter === 'all' })}
            aria-pressed={filter === 'all'}
            onClick={() => setFilter('all')}
          >
            All
          </button>
          {cats.map((c: string) => (
            <button
              key={c}
              type="button"
              className={cn('filter-pill', { active: filter === c })}
              aria-pressed={filter === c}
              onClick={() => setFilter(c)}
            >
              {c.charAt(0).toUpperCase() + c.slice(1)}
            </button>
          ))}
        </div>
      ) : null}

      {blogs.length === 0 ? (
        <p className="grid-empty">No posts published yet. Check back soon.</p>
      ) : visible.length === 0 ? (
        <p className="grid-empty">No posts match this filter.</p>
      ) : (
        <div className="doc-grid">
          {visible.map((b: Blog) => <DocCard key={b.id || b.title} doc={b} defaultKind="blog" />)}
        </div>
      )}
    </>
  );
}

import RichText from '@/components/RichText';
import { Books, Clock } from '@/components/icons';

/*
 * Documents → Book tab. Renders the founder's memoir-in-progress
 * snippets — a small section that lives alongside Stories and Blogs
 * but is intentionally lower-key. Per teww-cms-content-update-v2.md,
 * the founder's voice belongs in a contained place, not promoted on
 * the home page or main archive.
 */

export interface BookChapter {
  id?: string;
  num?: string;
  title?: string;
  readTime?: string;
  status?: string;
  snippet?: string;
  slug?: string;
  visible?: boolean;
}

export interface BookContent {
  eyebrow?: string;
  title?: string;
  subtitle?: string;
  intro?: string;
  chapters?: BookChapter[];
}

export default function BookTab({ book }: { book: BookContent }) {
  const chapters = (book.chapters || []).filter((c) => c?.visible !== false);

  return (
    <section className="section">
      <div className="section-inner">
        <div className="book-intro">
          <div className="section-eyebrow">{book.eyebrow || 'From the Book'}</div>
          <RichText as="h2" className="section-title book-title" html={book.title || 'The Book.'} />
          {book.subtitle ? (
            <div className="book-byline">
              <Books size="1em" aria-hidden="true" />
              <span>{book.subtitle}</span>
            </div>
          ) : null}
          {book.intro ? <p className="book-intro-text">{book.intro}</p> : null}
        </div>

        {chapters.length > 0 ? (
          <ol className="book-chapters" role="list">
            {chapters.map((c, i) => (
              <li key={c.id || i} className="book-chapter">
                <div className="book-chapter-meta">
                  <span className="book-chapter-num" aria-hidden="true">
                    {c.num || String(i + 1).padStart(2, '0')}
                  </span>
                  {c.readTime ? (
                    <span className="book-chapter-readtime">
                      <Clock size="1em" aria-hidden="true" /> {c.readTime}
                    </span>
                  ) : null}
                </div>
                <h3 className="book-chapter-title">{c.title || ''}</h3>
                {c.snippet ? <p className="book-chapter-snippet">{c.snippet}</p> : null}
                {c.status ? (
                  <div className="book-chapter-status">{c.status}</div>
                ) : null}
              </li>
            ))}
          </ol>
        ) : (
          <p style={{ color: 'var(--fg-muted)' }}>Chapters arriving soon.</p>
        )}

        <p className="book-foot">
          The book is in progress. Excerpts will publish here as chapters
          finalise — subscribe via the newsletter on the Blogs tab to be
          notified.
        </p>
      </div>
    </section>
  );
}

